create unique index if not exists health_units_municipality_cnes_unique_idx on public.health_units(municipality_id,cnes) where cnes is not null; create unique index if not exists health_professionals_municipality_cns_unique_idx on public.health_professionals(municipality_id,cns) where cns is not null; create index if not exists health_units_municipality_active_idx on public.health_units(municipality_id,active); create index if not exists health_professionals_municipality_active_idx on public.health_professionals(municipality_id,active); create index if not exists health_professional_links_professional_active_idx on public.health_professional_links(professional_id,active);